  input clk;
  input rst;
  input wr_en;
  input rd_en;
  input [7:0] din;
  output reg [7:0] dout;
  output full;
  output empty;

  reg [7:0] mem [0:15];
  reg [4:0] wr_ptr;
  reg [4:0] rd_ptr;

  wire ptr_addr_equal;
  wire write_valid;
  wire read_valid;

  assign ptr_addr_equal = (wr_ptr[3:0] == rd_ptr[3:0]);

  assign empty = ptr_addr_equal && (wr_ptr[4] == rd_ptr[4]);
  assign full  = ptr_addr_equal && (wr_ptr[4] != rd_ptr[4]);

  assign write_valid = wr_en && !full;
  assign read_valid  = rd_en && !empty;

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 5'd0;
      rd_ptr <= 5'd0;
      dout   <= 8'd0;
    end else begin
      if (write_valid) begin
        mem[wr_ptr[3:0]] <= din;
        wr_ptr <= wr_ptr + 5'd1;
      end

      if (read_valid) begin
        dout <= mem[rd_ptr[3:0]];
        rd_ptr <= rd_ptr + 5'd1;
      end
    end
  end

endmodule

